import{_ as r,a0 as i,w as p,s,ao as d,I as a,x as t,a1 as o,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在救援（單用户模式）/緊急模式下啓動 Ubuntu 18.04/Debian 9 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在救援（單用户模式）/緊急模式下啓動 Ubuntu 18.04/Debian 9 服務器 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在救援（單用户模式）/緊急模式下啓動 Ubuntu 18.04/Debian 9 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在救援（單用户模式）/緊急模式下啓動 Ubuntu 18.04/Debian 9 服務器 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180925 How to Boot Ubuntu 18.04 - Debian 9 Server in Rescue (Single User mode) - Emergency Mode","title":"如何在救援（單用户模式）/緊急模式下啓動 Ubuntu 18.04/Debian 9 服務器","tag":"201810","desc":""},"relativePath":"201810/20180925 How to Boot Ubuntu 18.04 - Debian 9 Server in Rescue (Single User mode) - Emergency Mode.md","filePath":"[post].md"}'),l={name:"201810/20180925 How to Boot Ubuntu 18.04 - Debian 9 Server in Rescue (Single User mode) - Emergency Mode.md"};function c(b,e,m,g,h,w){const n=i("Link");return p(),s("div",null,[e[15]||(e[15]=d('<h1 id="如何在救援-單用户模式-緊急模式下啓動-ubuntu-18-04-debian-9-服務器" tabindex="-1">如何在救援（單用户模式）/緊急模式下啓動 Ubuntu 18.04/Debian 9 服務器 <a class="header-anchor" href="#如何在救援-單用户模式-緊急模式下啓動-ubuntu-18-04-debian-9-服務器" aria-label="Permalink to “如何在救援（單用户模式）/緊急模式下啓動 Ubuntu 18.04/Debian 9 服務器”">​</a></h1><p>將 Linux 服務器引導到單用户模式或<ruby>救援模式<rt>rescue mode</rt></ruby>是 Linux 管理員在關鍵時刻恢復服務器時通常使用的重要故障排除方法之一。在 Ubuntu 18.04 和 Debian 9 中，單用户模式被稱為救援模式。</p><p>除了救援模式外，Linux 服務器可以在<ruby>緊急模式<rt>emergency mode</rt></ruby>下啓動，它們之間的主要區別在於，緊急模式加載了帶有隻讀根文件系統文件系統的最小環境，沒有啓用任何網絡或其他服務。但救援模式嘗試掛載所有本地文件系統並嘗試啓動一些重要的服務，包括網絡。</p><p>在本文中，我們將討論如何在救援模式和緊急模式下啓動 Ubuntu 18.04 LTS/Debian 9 服務器。</p><h4 id="在單用户-救援模式下啓動-ubuntu-18-04-lts-服務器" tabindex="-1">在單用户/救援模式下啓動 Ubuntu 18.04 LTS 服務器： <a class="header-anchor" href="#在單用户-救援模式下啓動-ubuntu-18-04-lts-服務器" aria-label="Permalink to “在單用户/救援模式下啓動 Ubuntu 18.04 LTS 服務器：”">​</a></h4><p>重啓服務器並進入啓動加載程序 （Grub） 屏幕並選擇 “Ubuntu”，啓動加載器頁面如下所示，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Bootloader-Screen-Ubuntu18-04-Server.jpg" alt=""></p><p>按下 <code>e</code>，然後移動到以 <code>linux</code> 開頭的行尾，並添加 <code>systemd.unit=rescue.target</code>。如果存在單詞 <code>$vt_handoff</code> 就刪除它。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/rescue-target-ubuntu18-04.jpg" alt=""></p><p>現在按 <code>Ctrl-x</code> 或 <code>F10</code> 啓動，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/rescue-mode-ubuntu18-04.jpg" alt=""></p><p>現在按回車鍵，然後你將得到所有文件系統都以讀寫模式掛載的 shell 並進行故障排除。完成故障排除後，可以使用 <code>reboot</code> 命令重新啓動服務器。</p><h4 id="在緊急模式下啓動-ubuntu-18-04-lts-服務器" tabindex="-1">在緊急模式下啓動 Ubuntu 18.04 LTS 服務器 <a class="header-anchor" href="#在緊急模式下啓動-ubuntu-18-04-lts-服務器" aria-label="Permalink to “在緊急模式下啓動 Ubuntu 18.04 LTS 服務器”">​</a></h4><p>重啓服務器並進入啓動加載程序頁面並選擇 “Ubuntu”，然後按 <code>e</code> 並移動到以 <code>linux</code> 開頭的行尾，並添加 <code>systemd.unit=emergency.target</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Emergecny-target-ubuntu18-04-server.jpg" alt=""></p><p>現在按 <code>Ctrl-x</code> 或 <code>F10</code> 以緊急模式啓動，你將獲得一個 shell 並從那裏進行故障排除。正如我們已經討論過的那樣，在緊急模式下，文件系統將以只讀模式掛載，並且在這種模式下也不會有網絡，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Emergency-prompt-debian9.jpg" alt=""></p><p>使用以下命令將根文件系統掛載到讀寫模式，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -o remount,rw /</span></span></code></pre></div><p>同樣，你可以在讀寫模式下重新掛載其餘文件系統。</p><h4 id="將-debian-9-引導到救援和緊急模式" tabindex="-1">將 Debian 9 引導到救援和緊急模式 <a class="header-anchor" href="#將-debian-9-引導到救援和緊急模式" aria-label="Permalink to “將 Debian 9 引導到救援和緊急模式”">​</a></h4><p>重啓 Debian 9.x 服務器並進入 grub頁面選擇 “Debian GNU/Linux”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Debian9-Grub-Screen.jpg" alt=""></p><p>按下 <code>e</code> 並移動到 linux 開頭的行尾並添加 <code>systemd.unit=rescue.target</code> 以在救援模式下啓動系統， 要在緊急模式下啓動，那就添加 <code>systemd.unit=emergency.target</code>。</p><h4 id="救援模式" tabindex="-1">救援模式： <a class="header-anchor" href="#救援模式" aria-label="Permalink to “救援模式：”">​</a></h4><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Rescue-mode-Debian9.jpg" alt=""></p><p>現在按 <code>Ctrl-x</code> 或 <code>F10</code> 以救援模式啓動</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Rescue-Mode-Shell-Debian9.jpg" alt=""></p><p>按下回車鍵以獲取 shell，然後從這裏開始故障排除。</p><h4 id="緊急模式" tabindex="-1">緊急模式： <a class="header-anchor" href="#緊急模式" aria-label="Permalink to “緊急模式：”">​</a></h4><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Emergency-target-grub-debian9.jpg" alt=""></p><p>現在按下 <code>ctrl-x</code> 或 <code>F10</code> 以緊急模式啓動系統</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Emergency-prompt-debian9.jpg" alt=""></p><p>按下回車獲取 shell 並使用 <code>mount -o remount,rw /</code> 命令以讀寫模式掛載根文件系統。</p><p><strong>注意：</strong>如果已經在 Ubuntu 18.04 和 Debian 9 Server 中設置了 root 密碼，那麼你必須輸入 root 密碼才能在救援和緊急模式下獲得 shell</p><p>就是這些了，如果您喜歡這篇文章，請分享你的反饋和評論。</p><hr>',37)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),o(n,{href:"https://www.linuxtechi.com/boot-ubuntu-18-04-debian-9-rescue-emergency-mode/"},{default:u(()=>[...e[0]||(e[0]=[t("https://www.linuxtechi.com/boot-ubuntu-18-04-debian-9-rescue-emergency-mode/",-1)])]),_:1})]),a("p",null,[e[6]||(e[6]=t("作者：",-1)),o(n,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:u(()=>[...e[2]||(e[2]=[t("Pradeep Kumar",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:u(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:u(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:u(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:u(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const D=r(l,[["render",c]]);export{T as __pageData,D as default};
